// === Tab: Bar ===
class Bar {

	constructor(x, y, w, h, r, clr) {
		this.x = x;
		this.y = y;
		this.w = w;
		this.h = h;
		this.r = r;
		this.clr = clr;
		this.eas = random([easeInOutBack, easeInOutElastic, easeInOutBounce]);
	}

	draw(t) {
		const f = this.eas(t);
		fill(this.clr);
		rect(this.x, this.y, this.w, this.h * f, this.r);
	}

}

function easeInOutBack(x) {
	const c1 = 1.70158;
	const c2 = c1 * 1.525;

	return x < 0.5 ?
		(Math.pow(2 * x, 2) * ((c2 + 1) * 2 * x - c2)) / 2 :
		(Math.pow(2 * x - 2, 2) * ((c2 + 1) * (x * 2 - 2) + c2) + 2) / 2;

}

function easeInOutElastic(x) {
	const c5 = (2 * Math.PI) / 4.5;

	return x === 0 ?
		0 :
		x === 1 ?
		1 :
		x < 0.5 ?
		-(Math.pow(2, 20 * x - 10) * Math.sin((20 * x - 11.125) * c5)) / 2 :
		(Math.pow(2, -20 * x + 10) * Math.sin((20 * x - 11.125) * c5)) / 2 + 1;

}

function easeInOutBounce(x) {
	return x < 0.5 ?
		(1 - easeOutBounce(1 - 2 * x)) / 2 :
		(1 + easeOutBounce(2 * x - 1)) / 2;

}

function easeInBounce(x) {
	return 1 - easeOutBounce(1 - x);
}

function easeOutBounce(x) {
	const n1 = 7.5625;
	const d1 = 2.75;

	if (x < 1 / d1) {
		return n1 * x * x;
	} else if (x < 2 / d1) {
		return n1 * (x -= 1.5 / d1) * x + 0.75;
	} else if (x < 2.5 / d1) {
		return n1 * (x -= 2.25 / d1) * x + 0.9375;
	} else {
		return n1 * (x -= 2.625 / d1) * x + 0.984375;
	}

}

// === Tab: mySketch ===
let bg, cbg, bars, startFrame, durationFrames = 120;

function setup() {
	createCanvas(windowWidth, windowHeight);
	frameRate(60);
	noStroke();
	cbg = color("#000000");
	init();
}

function init() {
	startFrame = frameCount;

	bars = [];

	const NUM = random(11, 19);
	const SZE = ~~(width / NUM);

	push();
	colorMode(HSB, 1);
	const hue = random();
	bg = color(fract(hue + random(0.3, 0.5)), random(0.2, 0.6), random(0.1, 0.2));

	for (let j = 0; j < 4; j++) {
		for (let x = 0, i = 0; i < NUM; x += SZE, i++) {
			const sat = random(0.2, 0.9)
			const clr = color(hue, sat, 1-sat, 0.25);
			const fh = random(0.9, 1.2);
			let bar;
			if (i % 2) {
				bar = new Bar(x, -SZE, SZE, fh * height + SZE, SZE / 2, clr)
			} else {
				bar = new Bar(x, height + SZE, SZE, -fh * height - SZE, SZE / 2, clr)
			}

			bars.push(bar);
		}
	}

	pop();
}

function mousePressed() {
	if ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) > 0.1 * width) init();
}

function draw() {
	cbg = lerpColor(cbg, bg, 0.02);
	background(cbg);

	if (frameCount > startFrame + 1.5 * durationFrames) {
		init();
	}

	const t = constrain((frameCount - startFrame) / durationFrames, 0, 1);
	var f = sin(t * PI);

	for (const b of bars) {
		b.draw(f);
	}
}
